INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('561aec23-10b2-58f4-9fff-cacc99a00dfb','TEXT','The Tiny Ferry','Sienna liked helping at the river workshop, especially when there was a small job that nobody had planned. One Friday, Sienna noticed the model ferry was not working as expected. The problem seemed simple at first, but the usual quick fix did not help. Sienna decided to stop and look carefully instead of rushing.
