INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('5a8f9fd2-31a2-5c20-bcc7-d796430423b1','TEXT','The Creek Sound Map','Luca liked helping at the creek reserve, especially when there was a small job that nobody had planned. One Thursday, Luca noticed the sound map was not working as expected. The problem seemed simple at first, but the usual quick fix did not help. Luca decided to stop and look carefully instead of rushing.
INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('de8509ba-1af3-5314-be42-a453ef10edba','TEXT','The Repaired Book — A Different Day','Zoe liked helping at the library corner, especially when there was a small job that nobody had planned. One Thursday, Zoe noticed the repair kit was not working as expected. The problem seemed simple at first, but the usual quick fix did not help. Zoe decided to stop and look carefully instead of rushing.
